  return {
    mode: extras.mode,
    mandate: state.mandate,
    portfolio: state.portfolioSnapshot,
    selectedInstruments,
    fundamentalReports,
    marketContext,
    ...(extras.proposal ? { proposal: extras.proposal } : {}),
    ...(extras.riskReport ? { riskReport: extras.riskReport } : {}),
