485	function withEvidenceLedger(
486	  runner: AgentRunner,
487	  state: InvestmentCommitteeState,
488	): AgentRunner {
489	  return {
490	    async run<TContext, TOutput>(
491	      definition: AgentDef<TContext, TOutput>,
492	      context: TContext,
493	    ) {
494	      const result = await runner.run(definition, context);
495	      mergeEvidence(state.evidence, result.evidence ?? []);
496	      if (result.graph) mergeGraph(state.graph, result.graph);
497	      return result;
498	    },
499	  };
500	}
501	
502	function mergeGraph(
503	  target: InvestmentCommitteeState["graph"],
504	  additions: InvestmentCommitteeState["graph"],
505	): void {
506	  const nodes = new Map(target.nodes.map((item) => [item.id, item]));
507	  const edges = new Map(target.edges.map((item) => [item.id, item]));
508	  for (const item of additions.nodes) mergeGraphRecord(nodes, item);
509	  for (const item of additions.edges) mergeGraphRecord(edges, item);
510	  target.nodes = [...nodes.values()];
511	  target.edges = [...edges.values()];
512	}
513	
514	function mergeGraphRecord<T extends { id: string }>(target: Map<string, T>, item: T): void {
515	  const existing = target.get(item.id);
516	  if (existing && JSON.stringify(existing) !== JSON.stringify(item)) {
517	    throw new Error(`Conflicting graph record "${item.id}".`);
518	  }
519	  target.set(item.id, item);
520	}
521	
522	function mergeEvidence(target: Evidence[], additions: readonly Evidence[]): void {
523	  const byId = new Map(target.map((item) => [item.id, item]));
524	  for (const item of additions) {
525	    const existing = byId.get(item.id);
526	    if (existing && JSON.stringify(existing) !== JSON.stringify(item)) {
527	      throw new Error(`Conflicting evidence record "${item.id}".`);
528	    }
529	    if (!existing) {
530	      target.push(item);
531	      byId.set(item.id, item);
532	    }
533	  }
534	}
