1	import type {
2	  InstrumentQuote,
3	  PaperOrder,
4	  PortfolioSnapshot,
5	  ProposedAction,
6	  MarketSnapshot,
7	} from "@sonar-ai/core";
8	
9	export interface ApplyPaperActionsInput {
10	  portfolio: PortfolioSnapshot;
11	  actions: readonly ProposedAction[];
12	  marketSnapshot: MarketSnapshot;
13	  appliedAt: string;
14	  orderIds?: ReadonlyMap<string, string>;
15	}
16	
17	/**
18	 * Deterministic internal paper ledger. It never calls a broker and never
19	 * decides whether an action is allowed; the orchestrator owns those gates.
20	 */
21	export function applyPaperActions(input: ApplyPaperActionsInput): {
22	  orders: PaperOrder[];
23	  portfolio: PortfolioSnapshot;
24	} {
25	  const quotes = new Map(input.marketSnapshot.quotes.map((quote) => [quote.instrumentId, quote]));
26	  const positions = new Map(
27	    input.portfolio.positions.map((position) => [position.instrumentId, { ...position }]),
28	  );
29	  let cash = input.portfolio.cash.amount;
30	  const orders: PaperOrder[] = [];
31	
32	  for (const action of input.actions) {
33	    const quote = quotes.get(action.instrumentId);
34	    if (!quote || quote.price <= 0) {
35	      throw new Error(`Paper ledger cannot price action "${action.id}".`);
36	    }
37	
38	    const notional = roundMoney(Math.abs(action.amount.amount));
39	    const quantity = roundQuantity(notional / quote.price);
40	    if (quantity <= 0) throw new Error(`Paper ledger action "${action.id}" has zero quantity.`);
41	
42	    const current = positions.get(action.instrumentId);
43	    const currentQuantity = current?.quantity ?? 0;
44	    const nextQuantity = action.side === "buy" ? currentQuantity + quantity : currentQuantity - quantity;
45	    if (nextQuantity < -1e-9) {
46	      throw new Error(`Paper ledger action "${action.id}" sells more than held.`);
47	    }
48	
49	    cash += action.side === "buy" ? -notional : notional;
50	    if (nextQuantity <= 1e-9) {
51	      positions.delete(action.instrumentId);
52	    } else {
53	      const marketValue = roundMoney(nextQuantity * quote.price);
54	      positions.set(action.instrumentId, {
55	        instrumentId: action.instrumentId,
56	        quantity: nextQuantity,
57	        avgPrice: { amount: quote.price, currency: quote.currency },
58	        marketValue: { amount: marketValue, currency: quote.currency },
59	        weight: marketValue / input.portfolio.nav.amount,
60	      });
61	    }
62	
63	    orders.push({
64	      id: input.orderIds?.get(action.id) ?? `ord_${action.id}`,
65	      actionId: action.id,
66	      instrumentId: action.instrumentId,
67	      side: action.side,
68	      quantity,
69	      price: { amount: quote.price, currency: quote.currency },
70	      notional: { amount: notional, currency: quote.currency },
71	      appliedAt: input.appliedAt,
72	    });
73	  }
74	
75	  const positionsList = [...positions.values()].sort((a, b) => a.instrumentId.localeCompare(b.instrumentId));
76	  return {
77	    orders,
78	    portfolio: {
79	      ...input.portfolio,
80	      id: `pf_after_${input.portfolio.id}`,
81	      asOf: input.appliedAt,
82	      cash: { amount: roundMoney(cash), currency: input.portfolio.baseCurrency },
83	      nav: input.portfolio.nav,
84	      positions: positionsList,
85	    },
86	  };
87	}
88	
89	function roundMoney(value: number): number {
90	  return Math.round(value * 100) / 100;
91	}
92	
93	function roundQuantity(value: number): number {
94	  return Math.round(value * 1_000_000) / 1_000_000;
95	}
96	
97	export function quoteFor(
98	  marketSnapshot: MarketSnapshot,
99	  instrumentId: string,
100	): InstrumentQuote | undefined {
101	  return marketSnapshot.quotes.find((quote) => quote.instrumentId === instrumentId);
102	}
