107	function sourceEvidence(
108	  provider: CalaProvider,
109	  title: string,
110	  snippet: string,
111	  source: CalaSource,
112	): Evidence {
113	  const rawDate = source.published_time ?? source.date;
114	  const parsedDate = rawDate ? new Date(rawDate) : null;
115	  const observedAt =
116	    parsedDate && !Number.isNaN(parsedDate.getTime())
117	      ? parsedDate.toISOString()
118	      : provider.mode === "fixture"
119	        ? "2026-08-29T00:00:00.000Z"
120	        : new Date().toISOString();
121	  const documentUrl = typeof source.document === "string" ? source.document : null;
122	  const candidateUrl = source.url ?? documentUrl;
123	  let sourceUrl: string | undefined;
124	  if (candidateUrl) {
125	    try {
126	      sourceUrl = new URL(candidateUrl).toString();
127	    } catch {
128	      sourceUrl = undefined;
129	    }
130	  }
131	  const id = `ev_cala_${createHash("sha256")
132	    .update(JSON.stringify({ title, snippet, source, observedAt }))
133	    .digest("hex")
134	    .slice(0, 16)}`;
135	  return EvidenceSchema.parse({
136	    id,
137	    kind: "cala",
138	    title,
139	    sourceName: source.name ?? source.source ?? "Cala",
140	    ...(sourceUrl ? { sourceUrl } : {}),
141	    observedAt,
142	    label:
143	      provider.mode === "fixture"
144	        ? "synthetic"
145	        : source.published_time || source.date
146	          ? "historical"
147	          : "live",
148	    snippet: snippet.slice(0, 300),
149	  });
