152	function profileEvidence(
153	  provider: CalaProvider,
154	  profile: CalaEntityProfile,
155	): Evidence[] {
156	  const evidence: Evidence[] = [];
157	  for (const [property, value] of Object.entries(profile.properties)) {
158	    for (const source of value.sources) {
159	      evidence.push(
160	        sourceEvidence(
161	          provider,
162	          `${profile.name}: ${property}`,
163	          `${property} = ${JSON.stringify(value.value)}`,
164	          source,
165	        ),
166	      );
167	    }
168	  }
169	  for (const metric of profile.numerical_observations) {
170	    if (metric.data?.length) {
171	      for (const point of metric.data) {
172	        if (!point.origin) continue;
173	        evidence.push(
174	          sourceEvidence(
175	            provider,
176	            `${profile.name}: ${metric.name ?? metric.id ?? "metric"}`,
177	            `value ${String(point.value)} at ${point.time ?? "unknown time"}`,
178	            point.origin,
179	          ),
180	        );
181	      }
182	    } else if (metric.origin) {
183	      evidence.push(
184	        sourceEvidence(
185	          provider,
186	          `${profile.name}: ${metric.name ?? metric.id ?? "metric"}`,
187	          `value ${String(metric.value)} at ${metric.time ?? metric.period ?? "unknown time"}`,
188	          metric.origin,
189	        ),
190	      );
191	    }
192	  }
193	  for (const direction of ["incoming", "outgoing"] as const) {
194	    for (const [relationshipType, relatedEntities] of Object.entries(
195	      profile.relationships[direction],
196	    )) {
197	      for (const related of relatedEntities) {
198	        for (const source of related.sources) {
199	          evidence.push(
200	            sourceEvidence(
201	              provider,
202	              `${profile.name}: ${relationshipType} ${related.name}`,
203	              `${direction} Cala relationship ${relationshipType}.`,
204	              source,
205	            ),
