import type { InvestmentCommitteeState } from "@sonar-ai/core";
import type { InstrumentStats, StressScenario } from "@sonar-ai/risk-engine";

/**
 * One run held between `POST /api/analysis/run` and its later approval. We keep
 * the deterministic risk inputs (`instrumentStats`, `stressScenarios`) next to
 * the state so the approval step can re-run the exact same risk checks the run
 * used — a model can't slip a different risk profile in between the two calls.
 */
export interface RunStoreEntry {
  state: InvestmentCommitteeState;
  instrumentStats?: InstrumentStats;
  stressScenarios?: readonly StressScenario[];
  updatedAt: string;
}

export interface RunStore {
  get(runId: string): RunStoreEntry | undefined;
  save(entry: RunStoreEntry): void;
  list(): RunStoreEntry[];
  clear(): void;
}

/**
 * In-memory run store. Deliberately simple: the demo runs in a single Next.js
 * process, so a module-level Map is enough to bridge run -> approve. It is NOT
 * durable — a server restart drops pending runs, and a horizontally scaled
 * deployment would need a shared store (Redis/Postgres). Recorded runs on disk
 * (see `record.ts`) remain the durable artifact for the demo replay.
 */
export class InMemoryRunStore implements RunStore {
  private readonly runs = new Map<string, RunStoreEntry>();

  get(runId: string): RunStoreEntry | undefined {
    return this.runs.get(runId);
  }

  save(entry: RunStoreEntry): void {
    this.runs.set(entry.state.run.id, entry);
  }

  list(): RunStoreEntry[] {
    return [...this.runs.values()];
  }

  clear(): void {
    this.runs.clear();
  }
}

// Process-wide singleton. Surviving module reloads in dev is out of scope; the
// store is only meant to bridge the two API calls of one demo session.
declare global {
  // eslint-disable-next-line no-var
  var __sonarRunStore: InMemoryRunStore | undefined;
}

export function getRunStore(): RunStore {
  globalThis.__sonarRunStore ??= new InMemoryRunStore();
  return globalThis.__sonarRunStore;
}

import { randomUUID } from "node:crypto";
import {
  DEMO_RISK_LIMITS,
  InvestmentCommitteeStateSchema,
  RiskLimitsSchema,
  type InvestmentCommitteeState,
  type PortfolioSnapshot,
  type RiskLimits,
} from "@sonar-ai/core";
import type { AlpacaPaperPortfolioSnapshot } from "@sonar-ai/core/alpaca";
import { z } from "zod";
import { resetToIdle } from "../runs/recording";

/**
 * The ONLY thing the human supplies to start a run: their risk appetite. The
 * committee chooses the companies (Cala discovery) — the user never picks
 * tickers. A preset maps to the four deterministic mandate limits; `limits`
 * lets an advanced caller override individual limits, but it can only make the
 * mandate tighter or equal, never wider than the preset — a request can't widen
 * risk beyond what the preset allows.
 */
export const RiskPreferencesSchema = z.object({
  riskTolerance: z
    .enum(["conservative", "balanced", "aggressive"])
    .default("balanced"),
  /** Optional per-limit overrides. Clamped to be no wider than the preset. */
  limits: RiskLimitsSchema.partial().optional(),
});
export type RiskPreferences = z.infer<typeof RiskPreferencesSchema>;

/**
 * Risk presets. `conservative` tightens every limit; `aggressive` loosens the
 * exposure/turnover ceilings and drops the cash floor. `balanced` is the demo
 * preset. None of these is investment advice — they are demo risk parameters.
 */
export const RISK_PRESET_LIMITS: Record<RiskPreferences["riskTolerance"], RiskLimits> = {
  conservative: {
    maxGrossExposurePerPosition: 0.15,
    maxSectorExposure: 0.3,
    minCashRatio: 0.25,
    maxTurnoverPerEvent: 0.1,
  },
  balanced: DEMO_RISK_LIMITS,
  aggressive: {
    maxGrossExposurePerPosition: 0.45,
    maxSectorExposure: 0.6,
    minCashRatio: 0.05,
    maxTurnoverPerEvent: 0.35,
  },
};

/**
 * Resolve the effective mandate limits. Overrides may only TIGHTEN the preset:
 * exposure/turnover ceilings are capped at the preset (min), and the cash floor
 * is raised to at least the preset (max). This guarantees a caller can never
 * use `limits` to widen risk past the preset it selected.
 */
export function resolveRiskLimits(prefs: RiskPreferences): RiskLimits {
  const preset = RISK_PRESET_LIMITS[prefs.riskTolerance];
  const o = prefs.limits;
  if (!o) return preset;
  return RiskLimitsSchema.parse({
    maxGrossExposurePerPosition: Math.min(
      preset.maxGrossExposurePerPosition,
      o.maxGrossExposurePerPosition ?? preset.maxGrossExposurePerPosition,
    ),
    maxSectorExposure: Math.min(
      preset.maxSectorExposure,
      o.maxSectorExposure ?? preset.maxSectorExposure,
    ),
    minCashRatio: Math.max(preset.minCashRatio, o.minCashRatio ?? preset.minCashRatio),
    maxTurnoverPerEvent: Math.min(
      preset.maxTurnoverPerEvent,
      o.maxTurnoverPerEvent ?? preset.maxTurnoverPerEvent,
    ),
  });
}

/**
 * Map a live Alpaca Paper snapshot (USD) to the core `PortfolioSnapshot` the
 * committee reasons over. Positions are resolved to core instrument ids via the
 * scenario universe (symbol match). An empty book — the demo starting state —
 * maps trivially. A held symbol that is not in the tradable universe is a hard
 * error: the committee must never reason over a position it can't identify.
 */
export function alpacaSnapshotToPortfolio(
  snapshot: AlpacaPaperPortfolioSnapshot,
  universe: InvestmentCommitteeState["candidateUniverse"],
): PortfolioSnapshot {
  const bySymbol = new Map(universe.map((i) => [i.symbol.toUpperCase(), i]));
  const nav = snapshot.portfolioValueUsd;
  const positions = snapshot.positions.map((position) => {
    const instrument = bySymbol.get(position.symbol.toUpperCase());
    if (!instrument) {
      throw new Error(
        `Alpaca holds "${position.symbol}", which is not in the tradable universe.`,
      );
    }
    return {
      instrumentId: instrument.id,
      quantity: position.quantity,
      avgPrice: { amount: position.averageEntryPriceUsd, currency: "USD" as const },
      marketValue: { amount: position.marketValueUsd, currency: "USD" as const },
      weight: nav > 0 ? position.marketValueUsd / nav : 0,
    };
  });
  return {
    id: `pf_alpaca_${snapshot.observedAt}`,
    asOf: snapshot.observedAt,
    baseCurrency: "USD",
    cash: { amount: snapshot.cashUsd, currency: "USD" },
    nav: { amount: nav, currency: "USD" },
    positions,
    label: snapshot.source === "live" ? "live" : "synthetic",
  };
}

export interface BuildIdleStateInput {
  /**
   * A validated committee state used as the analysis SCENARIO: it supplies the
   * tradable universe, market snapshot, discovered evidence and relationship
   * graph, and material events. Any phase is accepted — it is reset to idle.
   * (For the live path this is where Cala discovery + the Alpaca asset universe
   * are wired in; today the golden fixture stands in.)
   */
  scenario: InvestmentCommitteeState;
  riskPreferences: RiskPreferences;
  /**
   * A live/loaded Alpaca portfolio to run against. Used only when its currency
   * matches the scenario base currency; otherwise the scenario portfolio is
   * kept (USD-vs-EUR reconciliation is data-lane work, not decided here).
   */
  alpacaSnapshot?: AlpacaPaperPortfolioSnapshot;
  /** Run provenance label. Defaults to "synthetic". */
  label?: InvestmentCommitteeState["run"]["label"];
  /** Injectable clock/id for deterministic tests. */
  now?: string;
  runId?: string;
}

/**
 * Assemble a fresh, idle `InvestmentCommitteeState` ready for the orchestrator:
 * scenario inputs + a mandate derived from the user's risk preferences + the
 * portfolio to trade. The result is schema-validated, so a malformed scenario
 * or portfolio fails here rather than mid-run.
 */
export function buildIdleState(input: BuildIdleStateInput): InvestmentCommitteeState {
  const base = resetToIdle(input.scenario);
  const now = input.now ?? new Date().toISOString();
  const runId = input.runId ?? `run_${randomUUID()}`;

  const scenarioCurrency = base.portfolioSnapshot.baseCurrency;
  const useAlpaca =
    input.alpacaSnapshot !== undefined &&
    input.alpacaSnapshot.accountCurrency === scenarioCurrency;
  const portfolio = useAlpaca
    ? alpacaSnapshotToPortfolio(input.alpacaSnapshot!, base.candidateUniverse)
    : base.portfolioSnapshot;

  const limits = resolveRiskLimits(input.riskPreferences);

  const state: InvestmentCommitteeState = {
    ...base,
    run: {
      id: runId,
      scenarioId: base.run.scenarioId,
      startedAt: now,
      completedAt: null,
      label: input.label ?? "synthetic",
    },
    phase: "idle",
    portfolioSnapshot: portfolio,
    mandate: {
      ...base.mandate,
      id: `mnd_${runId}`,
      baseCurrency: portfolio.baseCurrency,
      initialCash: portfolio.cash,
      limits,
    },
  };

  return InvestmentCommitteeStateSchema.parse(state);
}

import {
  UserDecisionSchema,
  type InvestmentCommitteeState,
  type UserDecision,
} from "@sonar-ai/core";
import type { AlpacaOrderResponse, AlpacaPaperOrderRequest, AlpacaPaperPortfolioSnapshot } from "@sonar-ai/core/alpaca";
import type { InstrumentStats, StressScenario } from "@sonar-ai/risk-engine";
import { runRiskOfficer } from "./agents/risk-officer";
import { AnalysisOrchestrator } from "./orchestrator";
import type { AgentRunner } from "./runner/types";
import { buildIdleState, type RiskPreferences } from "./build-state";
import { getRunStore, type RunStore } from "../runs/run-store";

export interface AlpacaExecutor {
  submitPaperOrder(input: AlpacaPaperOrderRequest): Promise<AlpacaOrderResponse>;
}

/** Raised when the caller asks to act on a run the store doesn't hold. */
export class RunNotFoundError extends Error {
  constructor(public readonly runId: string) {
    super(`No analysis run found for id "${runId}".`);
    this.name = "RunNotFoundError";
  }
}

/** Raised when a run exists but isn't in a state that permits the operation. */
export class RunConflictError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "RunConflictError";
  }
}

export interface StartAnalysisRunInput {
  riskPreferences: RiskPreferences;
  /** The agent runner: OpenAI live, or a stub/recording runner offline. */
  runner: AgentRunner;
  /** Scenario supplying the universe, evidence, graph, and market snapshot. */
  scenario: InvestmentCommitteeState;
  /** A loaded Alpaca portfolio to run against (used when currency-compatible). */
  alpacaSnapshot?: AlpacaPaperPortfolioSnapshot;
  instrumentStats?: InstrumentStats;
  stressScenarios?: readonly StressScenario[];
  label?: InvestmentCommitteeState["run"]["label"];
  store?: RunStore;
  now?: string;
  runId?: string;
}

/**
 * Start one committee run. Assembles the idle state (risk preferences + Alpaca
 * portfolio + discovery scenario), runs the committee up to — and stopping at —
 * the human-approval gate (no `userDecision` is passed), then persists the run
 * so a later `approveAnalysisRun` can find and execute it.
 *
 * The run never mutates any ledger: discovery, research, proposal, deterministic
 * risk, critique, and revision all happen here, but nothing is applied until a
 * human approves.
 */
export async function startAnalysisRun(
  input: StartAnalysisRunInput,
): Promise<InvestmentCommitteeState> {
  const store = input.store ?? getRunStore();
  const state = buildIdleState({
    scenario: input.scenario,
    riskPreferences: input.riskPreferences,
    ...(input.alpacaSnapshot ? { alpacaSnapshot: input.alpacaSnapshot } : {}),
    ...(input.label ? { label: input.label } : {}),
    ...(input.now ? { now: input.now } : {}),
    ...(input.runId ? { runId: input.runId } : {}),
  });

  const orchestrator = new AnalysisOrchestrator({
    runner: input.runner,
    ...(input.instrumentStats ? { instrumentStats: input.instrumentStats } : {}),
    ...(input.stressScenarios ? { stressScenarios: input.stressScenarios } : {}),
  });

  // No userDecision: the committee halts at `awaiting_approval` (or `blocked`).
  const result = await orchestrator.run({ state });

  store.save({
    state: result,
    ...(input.instrumentStats ? { instrumentStats: input.instrumentStats } : {}),
    ...(input.stressScenarios ? { stressScenarios: input.stressScenarios } : {}),
    updatedAt: input.now ?? new Date().toISOString(),
  });

  return result;
}

export interface ApproveAnalysisRunInput {
  runId: string;
  decision: {
    decision: "approved" | "rejected";
    decidedBy?: string;
    note?: string;
  };
  /** The same runner used at run time (the report writer runs at approval). */
  runner: AgentRunner;
  /** Live Alpaca executor. Absent = internal deterministic paper ledger only. */
  alpacaClient?: AlpacaExecutor;
  store?: RunStore;
  now?: string;
}

/**
 * Apply a human decision to a pending run. Before anything is executed the
 * deterministic risk checks are RE-RUN on the exact actions being approved,
 * using the risk inputs captured at run time — a hard block here refuses the
 * approval outright, so no revision or timing gap can smuggle an action past a
 * limit the risk engine already enforced. On approval the orchestrator applies
 * the actions (to Alpaca Paper when an executor is provided, otherwise the
 * internal ledger), writes the report, and produces the decision receipt.
 */
export async function approveAnalysisRun(
  input: ApproveAnalysisRunInput,
): Promise<InvestmentCommitteeState> {
  const store = input.store ?? getRunStore();
  const entry = store.get(input.runId);
  if (!entry) throw new RunNotFoundError(input.runId);

  const state = entry.state;
  if (state.phase !== "awaiting_approval") {
    throw new RunConflictError(
      `Run "${input.runId}" is "${state.phase}", not awaiting approval.`,
    );
  }
  if (!state.finalRecommendation || !state.riskReport) {
    throw new RunConflictError(`Run "${input.runId}" has no recommendation to approve.`);
  }

  // Deterministic re-check on the approved actions. Independent of the model.
  const recheck = runRiskOfficer({
    portfolio: state.portfolioSnapshot,
    mandate: state.mandate,
    actions: state.finalRecommendation.actions,
    instruments: state.candidateUniverse,
    ...(entry.instrumentStats ? { instrumentStats: entry.instrumentStats } : {}),
    ...(entry.stressScenarios ? { stressScenarios: entry.stressScenarios } : {}),
    reportId: `rrp_recheck_${state.run.id}`,
  });
  if (recheck.hardBlocks.length > 0) {
    throw new RunConflictError(
      `Approval refused: deterministic risk re-check hard-blocked (${recheck.hardBlocks.join(", ")}).`,
    );
  }

  const decision: UserDecision = UserDecisionSchema.parse({
    decision: input.decision.decision,
    decidedAt: input.now ?? new Date().toISOString(),
    ...(input.decision.decidedBy ? { decidedBy: input.decision.decidedBy } : {}),
    ...(input.decision.note ? { note: input.decision.note } : {}),
  });

  const orchestrator = new AnalysisOrchestrator({
    runner: input.runner,
    ...(entry.instrumentStats ? { instrumentStats: entry.instrumentStats } : {}),
    ...(entry.stressScenarios ? { stressScenarios: entry.stressScenarios } : {}),
    ...(input.alpacaClient ? { alpacaClient: input.alpacaClient } : {}),
  });

  const result = await orchestrator.approve(state, decision);
  store.save({
    ...entry,
    state: result,
    updatedAt: decision.decidedAt,
  });
  return result;
}

