import "server-only";

import { normalizeAlpacaPaperPortfolio, type AlpacaPaperPortfolioSnapshot } from "@sonar-ai/core/alpaca";
import type { InvestmentCommitteeState } from "@sonar-ai/core";
import type { InstrumentStats, StressScenario } from "@sonar-ai/risk-engine";

import alpacaFixture from "@/fixtures/alpaca-paper-account.json";
// The golden fixture stands in as the discovery SCENARIO (universe + evidence +
// graph + market snapshot) until live Cala discovery + the Alpaca asset universe
// are wired in. See `build-state.ts`.
import { goldenState } from "../../../../../packages/core/src/__fixtures__/golden-state";
import type { ServerEnv } from "../env";
import { AlpacaPaperClient } from "../alpaca/client";
import { getAlpacaPaperConfig } from "../alpaca/config";
import { loadLatestRecording } from "../runs/record";
import { recordingToStubOutputs } from "../runs/recording";
import { createOpenAIAgentRunner } from "./runner/openai-runner";
import { StubAgentRunner } from "./runner/stub-runner";
import type { AgentRunner } from "./runner/types";
import type { AlpacaExecutor } from "./service";

/** Demo risk stats for the golden universe. Not real market data. */
export const DEMO_INSTRUMENT_STATS: InstrumentStats = {
  inst_nvidia: { volatility: 0.2, beta: 1.4 },
  inst_asml: { volatility: 0.18, beta: 1.3 },
  inst_siemens: { volatility: 0.1, beta: 0.9 },
  inst_vestas: { volatility: 0.22, beta: 1.1 },
  inst_sp500: { volatility: 0.08, beta: 1.0 },
};

export const DEMO_STRESS_SCENARIOS: readonly StressScenario[] = [
  { name: "AI capex slowdown", marketShock: -0.2 },
];

/**
 * Raised when a real run is requested offline but no recording exists to drive
 * the committee. Routes map this to 503 — record a run first, or go live.
 */
export class NoRecordingError extends Error {
  constructor() {
    super(
      "Offline mode needs a recorded run to drive the committee, but none was found. " +
        "Record one (`pnpm record:run` with a key) or set SONAR_OFFLINE=false.",
    );
    this.name = "NoRecordingError";
  }
}

export interface RunPlan {
  runner: AgentRunner;
  scenario: InvestmentCommitteeState;
  instrumentStats?: InstrumentStats;
  stressScenarios?: readonly StressScenario[];
  label: InvestmentCommitteeState["run"]["label"];
}

/**
 * Choose how a run executes from the environment:
 *  - LIVE (`SONAR_OFFLINE=false`): the real OpenAI committee over the discovery
 *    scenario, with the demo risk stats.
 *  - OFFLINE: a deterministic stub runner driven by the most recent recording —
 *    the committee still runs through every gate, but the agent outputs are the
 *    recorded ones, so it needs no API key. The recording's own state is the
 *    scenario, so discovery/research stay consistent with the recorded outputs.
 */
export async function resolveRunPlan(env: ServerEnv): Promise<RunPlan> {
  if (!env.SONAR_OFFLINE) {
    return {
      runner: createOpenAIAgentRunner(env),
      scenario: goldenState as InvestmentCommitteeState,
      instrumentStats: DEMO_INSTRUMENT_STATS,
      stressScenarios: DEMO_STRESS_SCENARIOS,
      label: "live",
    };
  }

  const recording = await loadLatestRecording();
  if (!recording) throw new NoRecordingError();
  return {
    runner: new StubAgentRunner(recordingToStubOutputs(recording)),
    scenario: recording.state,
    ...(recording.instrumentStats ? { instrumentStats: recording.instrumentStats } : {}),
    ...(recording.stressScenarios ? { stressScenarios: recording.stressScenarios } : {}),
    label: "historical",
  };
}

/**
 * Load the Alpaca Paper account + positions: the fixture snapshot offline, the
 * live paper account when online. Never touches live trading — read-only.
 */
export async function loadAlpacaSnapshot(env: ServerEnv): Promise<AlpacaPaperPortfolioSnapshot> {
  if (env.SONAR_OFFLINE) {
    return normalizeAlpacaPaperPortfolio(alpacaFixture.account, alpacaFixture.positions, {
      source: "fixture",
      observedAt: "2026-08-29T10:00:00Z",
    });
  }
  return new AlpacaPaperClient(getAlpacaPaperConfig()).getPortfolioSnapshot();
}

/**
 * The Alpaca order executor used at approval, or `undefined` offline (the
 * internal deterministic paper ledger applies actions instead).
 */
export function resolveAlpacaExecutor(env: ServerEnv): AlpacaExecutor | undefined {
  if (env.SONAR_OFFLINE) return undefined;
  return new AlpacaPaperClient(getAlpacaPaperConfig());
}

import { NextResponse } from "next/server";

import { RiskPreferencesSchema } from "@/lib/server/analysis/build-state";
import { startAnalysisRun } from "@/lib/server/analysis/service";
import { NoRecordingError, loadAlpacaSnapshot, resolveRunPlan } from "@/lib/server/analysis/wiring";
import { getServerEnv } from "@/lib/server/env";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/analysis/run
 *
 * Body: risk preferences only (the committee picks the companies).
 *   { "riskTolerance": "conservative" | "balanced" | "aggressive",
 *     "limits"?: { ...per-limit tightening overrides } }
 *
 * Loads the Alpaca Paper account, runs discovery → fundamentals → allocation →
 * deterministic risk → critique → revision, and STOPS at the human-approval
 * gate. Nothing is traded here. Returns the run id to approve next.
 */
export async function POST(request: Request): Promise<Response> {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    body = {}; // Empty body = all defaults (balanced).
  }

  const parsed = RiskPreferencesSchema.safeParse(body ?? {});
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid risk preferences.", issues: parsed.error.issues },
      { status: 400 },
    );
  }

  const env = getServerEnv();
  try {
    const plan = await resolveRunPlan(env);
    const alpacaSnapshot = await loadAlpacaSnapshot(env);

    const state = await startAnalysisRun({
      riskPreferences: parsed.data,
      runner: plan.runner,
      scenario: plan.scenario,
      alpacaSnapshot,
      label: plan.label,
      ...(plan.instrumentStats ? { instrumentStats: plan.instrumentStats } : {}),
      ...(plan.stressScenarios ? { stressScenarios: plan.stressScenarios } : {}),
    });

    // A deterministic gate (evidence/risk) may have blocked the run — surface it
    // as 422 rather than pretending it's awaiting approval.
    const status = state.phase === "blocked" ? 422 : 201;
    return NextResponse.json(
      { runId: state.run.id, phase: state.phase, state },
      { status },
    );
  } catch (error) {
    if (error instanceof NoRecordingError) {
      return NextResponse.json({ error: error.message }, { status: 503 });
    }
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Analysis run failed." },
      { status: 500 },
    );
  }
}

import { NextResponse } from "next/server";
import { z } from "zod";

import {
  RunConflictError,
  RunNotFoundError,
  approveAnalysisRun,
} from "@/lib/server/analysis/service";
import { resolveAlpacaExecutor, resolveRunPlan } from "@/lib/server/analysis/wiring";
import { getServerEnv } from "@/lib/server/env";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const ApproveBodySchema = z.object({
  decision: z.enum(["approved", "rejected"]),
  decidedBy: z.string().min(1).optional(),
  note: z.string().max(2000).optional(),
});

/**
 * POST /api/analysis/:runId/approve
 *
 * Body: { "decision": "approved" | "rejected", "decidedBy"?, "note"? }
 *
 * Requires explicit human approval. Re-runs the deterministic risk checks on the
 * exact actions being approved (a hard block refuses the approval), then, on
 * approval, submits the orders to Alpaca Paper (live) or the internal ledger
 * (offline), and returns the decision receipt with any Alpaca order ids.
 */
export async function POST(
  request: Request,
  ctx: { params: Promise<{ runId: string }> },
): Promise<Response> {
  const { runId } = await ctx.params;

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json(
      { error: "A JSON body with a `decision` is required." },
      { status: 400 },
    );
  }

  const parsed = ApproveBodySchema.safeParse(body);
  if (!parsed.success) {
    return NextResponse.json(
      { error: "Invalid approval decision.", issues: parsed.error.issues },
      { status: 400 },
    );
  }

  const env = getServerEnv();
  try {
    const plan = await resolveRunPlan(env);
    const alpacaClient = resolveAlpacaExecutor(env);

    const state = await approveAnalysisRun({
      runId,
      decision: parsed.data,
      runner: plan.runner,
      ...(alpacaClient ? { alpacaClient } : {}),
    });

    return NextResponse.json({
      runId: state.run.id,
      phase: state.phase,
      decision: state.userDecision,
      appliedOrders: state.appliedOrders,
      receipt: state.receipt,
      state,
    });
  } catch (error) {
    if (error instanceof RunNotFoundError) {
      return NextResponse.json({ error: error.message }, { status: 404 });
    }
    if (error instanceof RunConflictError) {
      return NextResponse.json({ error: error.message }, { status: 409 });
    }
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "Approval failed." },
      { status: 500 },
    );
  }
}

import type { InvestmentCommitteeState } from "@sonar-ai/core";
import { describe, expect, it } from "vitest";
// eslint-disable-next-line @typescript-eslint/no-restricted-imports
import { goldenState } from "../../../../../packages/core/src/__fixtures__/golden-state";
import { InMemoryRunStore } from "../runs/run-store";
import { StubAgentRunner } from "./runner/stub-runner";
import {
  RunConflictError,
  RunNotFoundError,
  approveAnalysisRun,
  startAnalysisRun,
} from "./service";

const INSTRUMENT_STATS = {
  inst_nvidia: { volatility: 0.2, beta: 1.4 },
  inst_siemens: { volatility: 0.1, beta: 0.9 },
};
const STRESS = [{ name: "AI capex slowdown", marketShock: -0.2 }] as const;

/** A stub whose canned outputs are the golden run — drives the full committee. */
function goldenRunner(): StubAgentRunner {
  return new StubAgentRunner({
    fundamental_analyst: goldenState.fundamentalReports,
    market_context: goldenState.marketContext!,
    portfolio_manager: [goldenState.proposal!, goldenState.finalRecommendation!],
    bear_critic: goldenState.bearCase!,
    report_writer: goldenState.report!,
  });
}

async function start(store: InMemoryRunStore, runner = goldenRunner()) {
  return startAnalysisRun({
    riskPreferences: { riskTolerance: "balanced" },
    runner,
    scenario: goldenState as InvestmentCommitteeState,
    instrumentStats: INSTRUMENT_STATS,
    stressScenarios: STRESS,
    store,
    now: "2026-08-29T15:00:00Z",
  });
}

describe("startAnalysisRun", () => {
  it("runs the committee to the human-approval gate and stores it", async () => {
    const store = new InMemoryRunStore();
    const state = await start(store);

    expect(state.phase).toBe("awaiting_approval");
    expect(state.finalRecommendation).not.toBeNull();
    expect(state.riskReport).not.toBeNull();
    // Nothing applied before approval.
    expect(state.userDecision).toBeNull();
    expect(state.appliedOrders).toEqual([]);
    expect(state.receipt).toBeNull();

    const stored = store.get(state.run.id);
    expect(stored?.state.phase).toBe("awaiting_approval");
    expect(stored?.instrumentStats).toEqual(INSTRUMENT_STATS);
  });

  it("mints a fresh run id and derives the mandate from risk preferences", async () => {
    const store = new InMemoryRunStore();
    const state = await start(store);
    expect(state.run.id).not.toBe(goldenState.run.id);
    // balanced preset == demo limits
    expect(state.mandate.limits.minCashRatio).toBe(0.1);
    expect(state.mandate.limits.maxGrossExposurePerPosition).toBe(0.3);
  });
});

describe("approveAnalysisRun", () => {
  it("applies actions on approval and produces a receipt", async () => {
    const store = new InMemoryRunStore();
    const runner = goldenRunner();
    const run = await start(store, runner);

    const approved = await approveAnalysisRun({
      runId: run.run.id,
      decision: { decision: "approved", decidedBy: "axel", note: "looks good" },
      runner,
      store,
      now: "2026-08-29T15:10:00Z",
    });

    expect(approved.phase).toBe("complete");
    expect(approved.userDecision?.decision).toBe("approved");
    expect(approved.appliedOrders.length).toBeGreaterThan(0);
    expect(approved.receipt).not.toBeNull();
    expect(approved.receipt?.runId).toBe(run.run.id);
    // Store reflects the completed run.
    expect(store.get(run.run.id)?.state.phase).toBe("complete");
  });

  it("records a rejection without applying any orders", async () => {
    const store = new InMemoryRunStore();
    const runner = goldenRunner();
    const run = await start(store, runner);

    const rejected = await approveAnalysisRun({
      runId: run.run.id,
      decision: { decision: "rejected" },
      runner,
      store,
      now: "2026-08-29T15:10:00Z",
    });

    expect(rejected.phase).toBe("complete");
    expect(rejected.userDecision?.decision).toBe("rejected");
    expect(rejected.appliedOrders).toEqual([]);
  });

  it("404s for an unknown run", async () => {
    const store = new InMemoryRunStore();
    await expect(
      approveAnalysisRun({
        runId: "run_nope",
        decision: { decision: "approved" },
        runner: goldenRunner(),
        store,
      }),
    ).rejects.toBeInstanceOf(RunNotFoundError);
  });

  it("409s when the run is not awaiting approval", async () => {
    const store = new InMemoryRunStore();
    const runner = goldenRunner();
    const run = await start(store, runner);
    await approveAnalysisRun({
      runId: run.run.id,
      decision: { decision: "approved" },
      runner,
      store,
      now: "2026-08-29T15:10:00Z",
    });
    // Second approval — already complete.
    await expect(
      approveAnalysisRun({
        runId: run.run.id,
        decision: { decision: "approved" },
        runner: goldenRunner(),
        store,
      }),
    ).rejects.toBeInstanceOf(RunConflictError);
  });
});

import type { InvestmentCommitteeState } from "@sonar-ai/core";
import type { AlpacaPaperPortfolioSnapshot } from "@sonar-ai/core/alpaca";
import { describe, expect, it } from "vitest";
// eslint-disable-next-line @typescript-eslint/no-restricted-imports
import { goldenState } from "../../../../../packages/core/src/__fixtures__/golden-state";
import {
  RISK_PRESET_LIMITS,
  alpacaSnapshotToPortfolio,
  buildIdleState,
  resolveRiskLimits,
} from "./build-state";

const scenario = goldenState as InvestmentCommitteeState;

describe("resolveRiskLimits", () => {
  it("returns the preset when no overrides are given", () => {
    expect(resolveRiskLimits({ riskTolerance: "aggressive" })).toEqual(
      RISK_PRESET_LIMITS.aggressive,
    );
  });

  it("lets overrides tighten but never widen the preset", () => {
    const limits = resolveRiskLimits({
      riskTolerance: "balanced",
      limits: {
        maxGrossExposurePerPosition: 0.9, // wider than preset -> clamped down
        minCashRatio: 0.5, // higher floor -> allowed
      },
    });
    expect(limits.maxGrossExposurePerPosition).toBe(
      RISK_PRESET_LIMITS.balanced.maxGrossExposurePerPosition,
    );
    expect(limits.minCashRatio).toBe(0.5);
  });
});

describe("buildIdleState", () => {
  it("assembles a valid idle state with a fresh id and preset-derived mandate", () => {
    const state = buildIdleState({
      scenario,
      riskPreferences: { riskTolerance: "conservative" },
      now: "2026-08-29T15:00:00Z",
      runId: "run_test1",
    });
    expect(state.phase).toBe("idle");
    expect(state.run.id).toBe("run_test1");
    expect(state.run.completedAt).toBeNull();
    expect(state.mandate.limits).toEqual(RISK_PRESET_LIMITS.conservative);
    // Scenario inputs are preserved.
    expect(state.candidateUniverse).toEqual(scenario.candidateUniverse);
    // Outputs are cleared.
    expect(state.finalRecommendation).toBeNull();
    expect(state.stages).toEqual([]);
  });

  it("keeps the scenario portfolio when the Alpaca currency doesn't match", () => {
    const usdSnapshot: AlpacaPaperPortfolioSnapshot = {
      provider: "alpaca",
      environment: "paper",
      source: "fixture",
      observedAt: "2026-08-29T10:00:00Z",
      accountCurrency: "USD",
      cashUsd: 100000,
      equityUsd: 100000,
      portfolioValueUsd: 100000,
      buyingPowerUsd: 100000,
      unrealizedPnlUsd: 0,
      tradingBlocked: false,
      accountBlocked: false,
      tradeSuspendedByUser: false,
      positions: [],
    };
    const state = buildIdleState({
      scenario, // EUR
      riskPreferences: { riskTolerance: "balanced" },
      alpacaSnapshot: usdSnapshot,
    });
    // EUR scenario kept, USD snapshot ignored (reconciliation is data-lane).
    expect(state.portfolioSnapshot.baseCurrency).toBe("EUR");
  });
});

describe("alpacaSnapshotToPortfolio", () => {
  const base = {
    provider: "alpaca" as const,
    environment: "paper" as const,
    source: "fixture" as const,
    observedAt: "2026-08-29T10:00:00Z",
    accountCurrency: "USD" as const,
    cashUsd: 100000,
    equityUsd: 100000,
    portfolioValueUsd: 100000,
    buyingPowerUsd: 100000,
    unrealizedPnlUsd: 0,
    tradingBlocked: false,
    accountBlocked: false,
    tradeSuspendedByUser: false,
  };

  it("maps an empty book to a cash-only USD portfolio", () => {
    const pf = alpacaSnapshotToPortfolio(
      { ...base, positions: [] },
      scenario.candidateUniverse,
    );
    expect(pf.baseCurrency).toBe("USD");
    expect(pf.cash.amount).toBe(100000);
    expect(pf.positions).toEqual([]);
  });

  it("throws on a held symbol outside the tradable universe", () => {
    expect(() =>
      alpacaSnapshotToPortfolio(
        {
          ...base,
          positions: [
