              assetId: "a1",
              symbol: "TSLA",
              quantity: 10,
              averageEntryPriceUsd: 200,
              marketValueUsd: 2200,
              costBasisUsd: 2000,
              unrealizedPnlUsd: 200,
              unrealizedPnlPct: 0.1,
              currentPriceUsd: 220,
            },
          ],
        },
        scenario.candidateUniverse,
      ),
    ).toThrow(/not in the tradable universe/);
  });
});

import type { InvestmentCommitteeState } from "@sonar-ai/core";
