57	  const maxToolOutputChars = request.maxToolOutputChars ?? 60_000;
58	  if (!Number.isInteger(maxToolOutputChars) || maxToolOutputChars < 1) {
59	    throw new Error("maxToolOutputChars must be a positive integer.");
60	  }
