95	        ...(evidence.size ? { evidence: [...evidence.values()] } : {}),
96	        ...(graphNodes.size || graphEdges.size
97	          ? { graph: { nodes: [...graphNodes.values()], edges: [...graphEdges.values()] } }
98	          : {}),
99	      };
100	    }
101	
102	    totalToolCalls += calls.length;
103	    if (totalToolCalls > maxToolCalls) {
104	      throw new Error(`OpenAI response exceeded ${maxToolCalls} tool calls.`);
105	    }
106	    if (remainingOutputTokens <= 0) {
107	      throw new Error("OpenAI response exhausted the stage output-token budget.");
108	    }
109	    if (typeof input === "string") {
110	      input = [{ role: "user", content: input }];
111	    }
112	    input.push(...(responseItems as ResponseInputItem[]));
113	
114	    for (const call of calls) {
115	      if (!toolNames.includes(call.name as ToolName)) {
116	        throw new Error(`OpenAI requested unavailable tool "${call.name}".`);
117	      }
118	      const tool = requireTool(registry, call.name as ToolName);
119	      const args = tool.inputSchema.parse(JSON.parse(call.arguments));
120	      const rawOutput = await tool.execute(args, request.toolContext ?? { offline: true });
121	      const parsedOutput = tool.outputSchema.parse(rawOutput);
122	      collectEvidence(parsedOutput, evidence);
123	      collectGraph(parsedOutput, graphNodes, graphEdges);
124	      const serializedOutput = JSON.stringify(parsedOutput);
125	      if (serializedOutput.length > maxToolOutputChars) {
126	        throw new Error(
127	          `Tool "${call.name}" output exceeded ${maxToolOutputChars} characters.`,
128	        );
129	      }
130	      input.push({
131	        type: "function_call_output",
132	        call_id: call.call_id,
133	        output: serializedOutput,
134	      });
135	    }
136	  }
137	}
138	
139	function collectGraph(
140	  value: unknown,
141	  nodes: Map<string, GraphNode>,
142	  edges: Map<string, GraphEdge>,
143	): void {
144	  if (!value || typeof value !== "object" || !("data" in value)) return;
145	  const data = (value as { data?: unknown }).data;
146	  if (!data || typeof data !== "object" || !("normalizedGraph" in data)) return;
147	  const parsed = RelationshipGraphSchema.safeParse(
148	    (data as { normalizedGraph?: unknown }).normalizedGraph,
149	  );
150	  if (!parsed.success) return;
151	  for (const node of parsed.data.nodes) mergeGraphItem(nodes, node);
152	  for (const edge of parsed.data.edges) mergeGraphItem(edges, edge);
153	}
154	
155	function mergeGraphItem<T extends { id: string }>(target: Map<string, T>, item: T): void {
156	  const existing = target.get(item.id);
157	  if (existing && JSON.stringify(existing) !== JSON.stringify(item)) {
158	    throw new Error(`Conflicting graph artifact "${item.id}".`);
159	  }
160	  target.set(item.id, item);
161	}
162	
163	function collectEvidence(value: unknown, target: Map<string, Evidence>): void {
164	  if (!value || typeof value !== "object" || !("evidence" in value)) return;
165	  const parsed = EvidenceSchema.array().safeParse(
166	    (value as { evidence?: unknown }).evidence,
167	  );
168	  if (!parsed.success) return;
169	  for (const item of parsed.data) target.set(item.id, item);
170	}
